import { AssetKind, kindOf } from './assets.js';

/**
 * What the sources WinASM65.Graphics generates define (AssetExporter): read
 * back from the `.asm` text, so that a label used in a program can be traced
 * to the asset and the item it was made from (the hover pictures).
 *
 * Every generated source starts with `; Generated by WinASM65.Graphics from
 * <asset file> - do not edit`, the asset being in the same folder. Labels are
 * `name:` lines, constants `NAME = value` lines.
 */

/** What a symbol stands for in its asset. */
export type SymbolRole =
  /** The palette table of a palette file. */
  | 'palettes'
  /** A palette's index constant (`PAL_SKY`); `ordinal` is the palette. */
  | 'palette'
  /** A metasprite's table or index constant; `ordinal` is the metasprite. */
  | 'metasprite'
  /** The address tables and the count of a metasprite file. */
  | 'metaspriteTable'
  /** An animation's table; `ordinal` is the animation. */
  | 'animation'
  | 'screen'
  | 'map';

export interface GeneratedSymbol {
  name: string;
  type: 'label' | 'constant';
  /** 0-based line of the definition in the generated source. */
  line: number;
  role: SymbolRole;
  ordinal?: number;
  value?: number;
}

export interface GeneratedSource {
  /** The asset file name, as the header gives it (relative to the source's folder). */
  source: string;
  kind: AssetKind;
  symbols: GeneratedSymbol[];
}

const HEADER = /^;\s*Generated by WinASM65\.Graphics from (.+?)(?:\s+-\s+do not edit)?\s*$/;
const LABEL = /^([A-Za-z_@.][\w@.]*):\s*(?:;.*)?$/;
const CONSTANT = /^([A-Za-z_@.][\w@.]*)\s*=\s*(\$[0-9A-Fa-f]+|%[01]+|\d+)\s*(?:;.*)?$/;

function parseNumber(text: string): number {
  if (text.startsWith('$')) return parseInt(text.slice(1), 16);
  if (text.startsWith('%')) return parseInt(text.slice(1), 2);
  return parseInt(text, 10);
}

/** The asset and the symbols of a generated source; undefined for any other text. */
export function parseGenerated(text: string): GeneratedSource | undefined {
  const lines = text.split(/\r?\n/);
  const header = HEADER.exec(lines[0] ?? '');
  if (!header) {
    return undefined;
  }
  const source = header[1].trim();
  const kind = kindOf(source);
  if (!kind || kind === 'chr') {
    return undefined;
  }

  // Labels with the directives under them, constants as they come.
  interface Block { name: string; line: number; directives: string[] }
  const blocks: Block[] = [];
  const constants: Array<{ name: string; line: number; value: number }> = [];
  let current: Block | undefined;
  lines.forEach((raw, line) => {
    const text = raw.trim();
    if (text === '' || text.startsWith(';')) {
      return;
    }
    const label = LABEL.exec(text);
    if (label && !/^\s/.test(raw)) {
      current = { name: label[1], line, directives: [] };
      blocks.push(current);
      return;
    }
    const constant = CONSTANT.exec(text);
    if (constant && !/^\s/.test(raw)) {
      constants.push({ name: constant[1], line, value: parseNumber(constant[2]) });
      current = undefined;
      return;
    }
    if (current && text.startsWith('.')) {
      current.directives.push(text.replace(/\s*;.*$/, ''));
    }
  });

  const symbols: GeneratedSymbol[] = [];
  const label = (block: Block, role: SymbolRole, ordinal?: number) =>
    symbols.push({ name: block.name, type: 'label', line: block.line, role, ordinal });
  const constant = (c: { name: string; line: number; value: number }, role: SymbolRole, ordinal?: number) =>
    symbols.push({ name: c.name, type: 'constant', line: c.line, role, ordinal, value: c.value });

  switch (kind) {
    case 'palette':
      blocks.forEach(b => label(b, 'palettes'));
      constants.forEach(c => constant(c, 'palette', c.value));
      break;
    case 'metasprite': {
      let sprites = 0;
      let animations = 0;
      for (const block of blocks) {
        const last = (block.directives[block.directives.length - 1] ?? '').replace(/\s+/g, ' ').toUpperCase();
        if (last === '.BYTE $80') {
          label(block, 'metasprite', sprites++);
        } else if (/^\.BYTE \$FF, [01]$/.test(last)) {
          label(block, 'animation', animations++);
        } else {
          label(block, 'metaspriteTable');
        }
      }
      for (const c of constants) {
        if (/METASPRITE_COUNT$/i.test(c.name) && c.value === sprites) {
          constant(c, 'metaspriteTable');
        } else {
          constant(c, 'metasprite', c.value);
        }
      }
      break;
    }
    case 'screen':
      blocks.forEach(b => label(b, 'screen'));
      constants.forEach(c => constant(c, 'screen'));
      break;
    case 'map':
      blocks.forEach(b => label(b, 'map'));
      constants.forEach(c => constant(c, 'map'));
      break;
  }
  return { source, kind, symbols };
}

/**
 * The `item` of the designer's `render` request that draws what a symbol
 * stands for: a metasprite's name, an animation's first frame
 * (`name#0`), or undefined for the whole asset (or its first metasprite).
 */
export function renderItem(symbol: GeneratedSymbol, asset: unknown): string | undefined {
  const a = asset as { metasprites?: Array<{ name?: string }>; animations?: Array<{ name?: string }> } | undefined;
  if (symbol.role === 'metasprite' && symbol.ordinal !== undefined) {
    return a?.metasprites?.[symbol.ordinal]?.name ?? undefined;
  }
  if (symbol.role === 'animation' && symbol.ordinal !== undefined) {
    const name = a?.animations?.[symbol.ordinal]?.name;
    return name ? name + '#0' : undefined;
  }
  return undefined;
}

/** What a symbol is, in words: `metasprite "ship"`, `animation "fly", frame 0`. */
export function describeSymbol(symbol: GeneratedSymbol, item: string | undefined): string {
  switch (symbol.role) {
    case 'palettes': return 'palettes';
    case 'palette': return 'palette ' + symbol.ordinal;
    case 'metasprite': return item ? 'metasprite "' + item + '"' : 'metasprite ' + symbol.ordinal;
    case 'metaspriteTable': return 'metasprite tables (first metasprite shown)';
    case 'animation': return item ? 'animation "' + item.replace(/#0$/, '') + '", frame 0' : 'animation ' + symbol.ordinal;
    case 'screen': return 'screen';
    case 'map': return 'map';
  }
}

/** An `.incbin "file"` or `.include "file"` line: the directive, the file, and where the file name is. */
export function parseIncludeLine(line: string): { directive: 'incbin' | 'include'; file: string; start: number; end: number } | undefined {
  const match = /^(\s*(?:[A-Za-z_@.][\w@.]*:?\s+)?)\.(incbin|include)(\s+)"([^"]+)"/i.exec(line);
  if (!match) {
    return undefined;
  }
  const start = match[1].length;
  return {
    directive: match[2].toLowerCase() as 'incbin' | 'include',
    file: match[4],
    start,
    end: start + 1 + match[2].length + match[3].length + match[4].length + 2
  };
}

/**
 * The asset that a file a program includes was made from, by name: a tile set
 * is its own asset, `x.nam` / `x.rle` come from `x.screen.json`, `x.pal.bin`
 * from `x.pal.json`. Undefined for a generated `.asm` (its header says) and
 * anything else.
 */
export function assetOfIncluded(file: string): string | undefined {
  const lower = file.toLowerCase();
  if (lower.endsWith('.chr')) return file;
  if (lower.endsWith('.nam') || lower.endsWith('.rle')) return file.slice(0, -4) + '.screen.json';
  if (lower.endsWith('.pal.bin')) return file.slice(0, -8) + '.pal.json';
  if (kindOf(file) && kindOf(file) !== 'chr') return file;
  return undefined;
}
